#include "ann_log.h"
#include <stdio.h>
static const char*names[]={"invalid","generated","frame_rx","rx","confirmed","expired","cancelled","rejected","duplicate","echo"};
static void line(const ann_console*c,const char*event,ann_id origin,uint32_t boot,uint32_t seq,unsigned frame,unsigned payload,int status,uint64_t now,uint32_t attempt,char*out,size_t cap,int unique){char id[18],o[18],a[24]="null";ann_id_text(c->node->id,id);ann_id_text(origin,o);if(attempt)snprintf(a,sizeof(a),"%lu",(unsigned long)attempt);snprintf(out,cap,"{\"schema\":\"ann.serial.v1\",\"event\":\"%s\",\"nonce\":null,\"run_id\":%s%s%s,\"node_id\":\"%s\",\"boot_id\":\"%08lx\",\"origin_id\":\"%s\",\"origin_boot_id\":\"%08lx\",\"seq\":%lu,\"t_us\":%llu,\"frame_bytes\":%u,\"payload_bytes\":%u,\"status\":%d,\"tx_attempt\":%s,\"unique_receive\":%s,\"evidence_kind\":\"%s\",\"airtime_us\":null,\"rf_retries\":null}",event,c->run_id[0]?"\"":"",c->run_id[0]?c->run_id:"null",c->run_id[0]?"\"":"",id,(unsigned long)c->node->boot,o,(unsigned long)boot,(unsigned long)seq,(unsigned long long)(now*1000),frame,payload,status,a,unique?"true":"false",c->chip[0]=='h'?"synthetic":"firmware_event");}
void ann_log_event(const ann_console*c,const ann_event*e,char*out,size_t cap){line(c,e->type<=9?names[e->type]:"invalid",e->origin,e->boot,e->seq,e->frame_bytes,e->payload_bytes,e->status,e->t_ms,0,out,cap,e->type==ANN_DELIVERED||e->type==ANN_ECHOED);}
void ann_log_tx(const ann_console*c,const ann_out*t,const char*event,int status,uint64_t now,uint32_t attempt,char*out,size_t cap){line(c,event,t->packet.origin,t->packet.boot,t->packet.seq,112+t->packet.payload_len,t->packet.payload_len,status,now,attempt,out,cap,0);}
void ann_log_echo(const ann_console*c,const ann_packet*p,uint64_t now,char*out,size_t cap){char id[18],origin[18];uint32_t boot,seq;if(p->payload_len<8)return;boot=(uint32_t)p->payload[0]|(uint32_t)p->payload[1]<<8|(uint32_t)p->payload[2]<<16|(uint32_t)p->payload[3]<<24;seq=(uint32_t)p->payload[4]|(uint32_t)p->payload[5]<<8|(uint32_t)p->payload[6]<<16|(uint32_t)p->payload[7]<<24;ann_id_text(c->node->id,id);ann_id_text(p->origin,origin);snprintf(out,cap,"{\"schema\":\"ann.serial.v1\",\"event\":\"echo_correlation\",\"nonce\":null,\"run_id\":%s%s%s,\"node_id\":\"%s\",\"boot_id\":\"%08lx\",\"origin_id\":\"%s\",\"origin_boot_id\":\"%08lx\",\"seq\":%lu,\"request_origin_id\":\"%s\",\"request_boot_id\":\"%08lx\",\"request_seq\":%lu,\"same_source_boot\":%s,\"t_us\":%llu,\"frame_bytes\":%u,\"payload_bytes\":%u,\"unique_receive\":false,\"tx_attempt\":null,\"rtt_ms\":null,\"evidence_kind\":\"%s\"}",c->run_id[0]?"\"":"",c->run_id[0]?c->run_id:"null",c->run_id[0]?"\"":"",id,(unsigned long)c->node->boot,origin,(unsigned long)p->boot,(unsigned long)p->seq,id,(unsigned long)boot,(unsigned long)seq,boot==c->node->boot?"true":"false",(unsigned long long)(now*1000),112+p->payload_len,p->payload_len,c->chip[0]=='h'?"synthetic":"firmware_event");}
